const { AsyncLocalStorage } = require('node:async_hooks');
const als = new AsyncLocalStorage();

// Minimal OTel-style context API backed by AsyncLocalStorage.
const context = {
  active: () => als.getStore() || {},
  with: (ctx, fn) => als.run(ctx, fn),
  bind: (ctx, fn) => (...args) => als.run(ctx, () => fn(...args)),
};

function handler(done) {
  // request context already active: trace-id = 'abc123'
  let seen = null;
  // BROKEN: traceparent lost across the setTimeout
  setTimeout(() => {
    seen = (context.active().traceId) || 'ORPHAN';
    console.log(seen);
    done();
  }, 0);
}

context.with({ traceId: 'abc123' }, () => handler(() => {}));
